changeSet.sql:
GRANT USAGE ON SCHEMA whiteboard TO ${app_user};
GRANT SELECT, INSERT, UPDATE, DELETE ON
    whiteboard.whiteboard,
    whiteboard.whiteboard_snapshot,
    whiteboard.whiteboard_draft,
    whiteboard.whiteboard_create_receipt TO ${app_user};

rollback.sql:
REVOKE SELECT, INSERT, UPDATE, DELETE ON
    whiteboard.whiteboard,
    whiteboard.whiteboard_snapshot,
    whiteboard.whiteboard_draft,
    whiteboard.whiteboard_create_receipt FROM ${app_user};
REVOKE USAGE ON SCHEMA whiteboard FROM ${app_user};
